import{_ as e,o as i,c as r,a2 as o}from"./chunks/framework.D8Tso2Ul.js";const t="/manual/img/actividades/inicio.png",s="/manual/img/actividades/nueva-actividad.png",v=JSON.parse('{"title":"Actividades y capacitación","description":"","frontmatter":{},"headers":[],"relativePath":"modulos/actividades.md","filePath":"modulos/actividades.md"}'),n={name:"modulos/actividades.md"};function l(d,a,c,u,g,m){return i(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="actividades-y-capacitacion" tabindex="-1">Actividades y capacitación <a class="header-anchor" href="#actividades-y-capacitacion" aria-label="Permalink to &quot;Actividades y capacitación&quot;">​</a></h1><p>El módulo de <strong>Actividades</strong> te permite programar y registrar todo lo que reúne a los trabajadores en torno a la seguridad: <strong>capacitaciones</strong>, <strong>charlas de inicio de jornada</strong>, <strong>simulacros</strong> y otras actividades preventivas. Lo más importante es que aquí queda el <strong>registro de asistencia firmado</strong>, que es la prueba de que la capacitación efectivamente se realizó (una exigencia clave del DS 44, Art. 16).</p><h2 id="entrar-al-modulo" tabindex="-1">Entrar al módulo <a class="header-anchor" href="#entrar-al-modulo" aria-label="Permalink to &quot;Entrar al módulo&quot;">​</a></h2><p>En el menú lateral, haz clic en <strong>Actividades</strong>. Se abrirá la pantalla <strong>&quot;Actividades y capacitación&quot;</strong>.</p><blockquote><p>📌 Las actividades se gestionan <strong>por obra</strong>. Si ves el mensaje <em>&quot;Seleccione una obra para ver sus actividades&quot;</em>, elige primero la obra con la que quieres trabajar (en el selector de obra, normalmente arriba). Una vez seleccionada, verás sus actividades.</p></blockquote><p>La pantalla se organiza en dos bloques:</p><ul><li><strong>Actividades de Hoy</strong> — lo programado para el día, listo para registrar asistencia.</li><li><strong>Historial de Actividades</strong> — todo lo que ya se realizó.</li></ul><p><img src="'+t+'" alt="Pantalla de Actividades mostrando las actividades de hoy y el historial"></p><h2 id="programar-una-actividad-nueva" tabindex="-1">Programar una actividad nueva <a class="header-anchor" href="#programar-una-actividad-nueva" aria-label="Permalink to &quot;Programar una actividad nueva&quot;">​</a></h2><ol><li>Haz clic en el botón <strong>Nueva Actividad</strong>.</li><li>Completa el formulario: <ul><li><strong>Tipo de Actividad</strong> <em>(obligatorio)</em> — capacitación, charla, simulacro, etc.</li><li><strong>Tipo de capacitación (DS44)</strong> <em>(obligatorio si es capacitación)</em> — el tipo específico que exige la normativa.</li><li><strong>Título</strong> <em>(obligatorio)</em> — un nombre claro (ej.: <em>&quot;Uso correcto de EPP&quot;</em>).</li><li><strong>Descripción</strong> <em>(opcional)</em> — de qué tratará.</li><li><strong>Relator</strong> <em>(obligatorio)</em> — quién dictará la actividad.</li><li><strong>Fecha</strong> <em>(obligatorio)</em> — cuándo se realizará.</li><li><strong>Periodicidad</strong> — si es una actividad <strong>única</strong> o se <strong>repite</strong> (en cuyo caso indicas hasta cuándo).</li><li><strong>Hora inicio</strong> <em>(obligatorio)</em> y <strong>Hora fin</strong> <em>(opcional)</em>.</li><li><strong>Ubicación</strong> <em>(opcional)</em> — dónde se hará (ej.: <em>&quot;Frente de obra, sala de charlas&quot;</em>).</li><li><strong>Trabajadores</strong> — marca quiénes deben asistir (solo aparecen los asignados a la obra).</li></ul></li><li>Guarda. La actividad quedará programada y aparecerá en la agenda de la obra.</li></ol><p><img src="'+s+'" alt="Formulario de Nueva Actividad con los campos de tipo, relator y fecha"></p><blockquote><p>💡 Si una charla se repite (por ejemplo, la charla diaria de 5 minutos), usa la opción de <strong>periodicidad</strong> para no tener que crearla manualmente cada día.</p></blockquote><h2 id="registrar-la-asistencia" tabindex="-1">Registrar la asistencia <a class="header-anchor" href="#registrar-la-asistencia" aria-label="Permalink to &quot;Registrar la asistencia&quot;">​</a></h2><p>Una actividad solo cuenta como <strong>realizada</strong> cuando queda registrada la asistencia de los trabajadores. Hay dos formas:</p><ul><li><strong>Registrar Asistencia</strong> (el relator o gestor) — abre la lista de trabajadores y marca quiénes asistieron. Cada asistente confirma con su firma. Los que ya están registrados se muestran con la etiqueta <strong>&quot;Ya registrado&quot;</strong>.</li><li><strong>Registrar mi asistencia</strong> (el propio trabajador) — cada persona puede confirmar su asistencia y firmar desde su cuenta.</li></ul><blockquote><p>✅ La firma de asistencia es la evidencia legal de la capacitación. Sin asistencia firmada, la actividad queda como pendiente y <strong>no cuenta</strong> para el cumplimiento de la obra.</p></blockquote><h2 id="ver-el-detalle-de-una-actividad" tabindex="-1">Ver el detalle de una actividad <a class="header-anchor" href="#ver-el-detalle-de-una-actividad" aria-label="Permalink to &quot;Ver el detalle de una actividad&quot;">​</a></h2><p>Haz clic sobre cualquier actividad para abrir su <strong>Detalle</strong>, donde verás la fecha, el horario, el relator, la descripción y la lista de <strong>asistentes</strong> con su estado de firma.</p><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h2><p><strong>No veo ninguna actividad.</strong> Probablemente no has seleccionado una obra. Las actividades se muestran <strong>por obra</strong>: elige una en el selector de obra y aparecerán sus actividades.</p><p><strong>Programé la actividad pero no aparece como cumplida.</strong> Una actividad se considera cumplida cuando tiene <strong>asistencia registrada y firmada</strong>. Mientras nadie firme la asistencia, quedará pendiente.</p><p><strong>¿Quién puede crear actividades?</strong> Los roles de gestión (Administrador, Prevencionista, Jefe de Obra, Supervisor). El relator asignado es quien la dicta. Consulta <a href="/manual/roles/">Roles de Usuario</a>.</p><p><strong>Un trabajador faltó a la capacitación. ¿Qué hago?</strong> Simplemente no lo marques como asistente. Quedará registrado que no asistió, y podrás reprogramarle la capacitación más adelante.</p><p><strong>¿La asistencia se puede firmar en terreno sin señal?</strong> La firma de asistencia usa el mismo sistema de PIN de las firmas. Si no hay conexión, revisa las opciones de <a href="/manual/modulos/firmas.html">Firmas Offline</a> para recolectarlas y sincronizarlas luego.</p><p><strong>¿Cómo programo la charla diaria que se repite todos los días?</strong> Al crear la actividad, elige la <strong>periodicidad</strong> correspondiente e indica hasta qué fecha se repite. El sistema generará las ocurrencias por ti.</p>',25)])])}const b=e(n,[["render",l]]);export{v as __pageData,b as default};
